#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe surl-keep-the-server-log-for-a-failed-run. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
cat > site/report.csv <<'EOF'
id,total
1,40
EOF
cat > tests.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# The tests of a CI run: the report over HTTPS with a password, then with a token, then
# over FTPS; the first failure ends the run with curl's exit code.
# Usage: sh tests.sh <https port> <ftps port> <ftps password>
set -e
curl -sSf --cacert server.pem -u app:s3cret -o /dev/null "https://127.0.0.1:$1/report.csv"
curl -sSf --cacert server.pem --oauth2-bearer tok-7f3a9c -o /dev/null "https://127.0.0.1:$1/report.csv"
curl -sSf --cacert server.pem -u "app:$3" -o /dev/null "ftps://127.0.0.1:$2/report.csv"
EOF
cat > ci-step.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# A CI step: run the tests; if they fail, keep surl's trace in ci-logs/ for the job to
# upload, and fail with the tests' exit code. surl has already withheld the passwords and
# tokens of HTTPS and FTPS from the trace.
# Usage: sh ci-step.sh <test command> [<argument>...]
"$@" && exit 0
status=$?
# surl traces an exchange's last lines a moment after its client has gone: wait, at most 10 s,
# until every exchange the trace opened has ended.
i=0; until [ "$(grep -c 'Exchange [0-9]* opened: ' trace.txt)" -eq "$(grep -c 'Exchange [0-9]* ended; ' trace.txt)" ]; do i=$((i+1)); [ $i -ge 100 ] && break; sleep 0.1; done
mkdir -p ci-logs
cp trace.txt ci-logs/trace.txt
exit "$status"
EOF
cat > drop-received.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Print a trace without the bytes clients sent: no user names, paths or other client data.
# After a "<= Recv data" line come the bytes a client sent, one offset-led line each, up to
# the next line that starts with an exchange number. Drop those bytes; keep everything else.
# Usage: sh drop-received.sh <trace file>
awk '/^#[0-9]+ <= Recv data/ { print; skip = 1; next }
     /^#[0-9]+ / { skip = 0 }
     !skip' "$1"
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --trace-ascii trace.txt --directory site --cert server.pem --key server.key --user app:s3cret --user :tok-7f3a9c https://127.0.0.1:8080/ ftps://127.0.0.1:8081/ &
sleep 1
sh ci-step.sh sh tests.sh 8080 8081 guess || true
kill $(jobs -p)
